import 'dart:convert';
import 'dart:io';

import 'package:fitness_tracker/ml/pose_classifier.dart';
import 'package:fitness_tracker/ml/pose_frame.dart';
import 'package:flutter_test/flutter_test.dart';

/// Verifies the pure-Dart network gives the same output as the original Keras
/// weights evaluated with NumPy (fixtures generated by tools/convert_models.py).
void main() {
  const models = [
    'pushup_updown',
    'pushup_form',
    'squat_updown',
    'hammer_curl_updown',
    'barbell_curl_updown',
  ];

  for (final name in models) {
    test('$name matches NumPy reference', () {
      final model = PoseClassifier.fromJson(
        jsonDecode(File('assets/models/$name.json').readAsStringSync()) as Map<String, dynamic>,
      );
      final fixture =
          jsonDecode(File('test/fixtures/${name}_fixture.json').readAsStringSync()) as Map<String, dynamic>;
      final inputs = (fixture['inputs'] as List).cast<List>();
      final outputs = (fixture['outputs'] as List).cast<List>();

      for (var i = 0; i < inputs.length; i++) {
        final x = inputs[i].map((v) => (v as num).toDouble()).toList();
        final expected = outputs[i].map((v) => (v as num).toDouble()).toList();
        final actual = model.predict(x);
        expect(actual.length, expected.length);
        for (var j = 0; j < expected.length; j++) {
          expect(actual[j], closeTo(expected[j], 1e-6));
        }
      }
    });
  }

  test('extractFeatures makes landmarks relative to the nose', () {
    final points = List.generate(33, (i) => PosePoint(0.5 + i / 100, 0.2 + i / 50));
    final features = extractFeatures(PoseFrame(points));
    expect(features.length, 66);
    expect(features[0], 0);
    expect(features[1], 0);
    expect(features[2], closeTo(0.01, 1e-9));
    expect(features[3], closeTo(0.02, 1e-9));
  });
}
